const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const {chromium} = require('playwright');
const {context, render, server} = require('./marcela-harness.cjs');
const temp = process.env.MARCELA_VALIDATION_DIR || 'C:/Temp/eora-marcela-validation';
const base = 'http://127.0.0.1:4180/favoritosdamarcela/';
const read = f => fs.readFileSync(f, 'utf8');
for (const file of ['static/js/marcela.js', 'static/js/best-sellers-eora.js']) new vm.Script(read(file));
const schema = read('config/settings.txt');
const names = [...schema.matchAll(/^\s*name\s*=\s*(\S+)/gm)].map(m => m[1]);
assert.equal(new Set(names).size, names.length, 'no duplicate editor fields');
assert.match(schema, /^Favoritos da Marcela\r?$/m);
for (let i = 1; i <= 15; i++) assert(names.includes('marcela_category_' + i + '_tag'));
for (let i = 1; i <= 10; i++) for (const kind of ['catalog', 'look', 'founder']) assert(names.includes('marcela_' + kind + '_' + i + '_enabled'));
const disabled = render(context({categories: 0, looks: 0, founder: 0}));
assert(!disabled.includes('data-mf-look="'));
assert(!disabled.includes('class="mf-founder-card"'));
const gifContext = context();
gifContext.settings.marcela_founder_1_image = [{image: 'mf-upload-original.gif'}];
assert.match(render(gifContext), /src="\/fixtures\/source-original\.gif"/);
assert.doesNotMatch(render(gifContext), /src(?:set)?="mf-upload-/);
const newDesktopOnly = context();
newDesktopOnly.settings.marcela_hero_image_mobile = [];
assert.doesNotMatch(render(newDesktopOnly).match(/<section class="mf-hero"[\s\S]*?<\/section>/)[0], /legacy-mobile/, 'new desktop hero must not reuse the old campaign mobile');
const legacy = render(context({legacy: true}));
assert(legacy.includes('data-be-product="900009"'), 'legacy campaign product list retained');
for (const file of ['layouts/layout.tpl', 'static/js/store.js.tpl']) {
    const rules = read(file).match(/\{% set is_marcela_page =[^\n]+\n\s*\{% set is_best_sellers_eora_page =[^\n]+\n\s*\{% set is_on_campaign_page =[^\n]+/)[0];
    const Twig = require('twig');
    const template = Twig.twig({data: rules + '{{ is_on_campaign_page ? "legacy" : "dedicated" }}', rethrow: true});
    const vars = {template: 'page', settings: {}, page: {handle: 'favoritosdamarcela'}, page_current_04: 'favoritosdamarcela', is_campaign_04: true};
    assert.equal(template.render(vars).trim(), 'dedicated', 'new page must not initialize legacy campaign CSS/sliders');
    vars.page.handle = 'outra-campanha'; vars.page_current_04 = 'outra-campanha';
    assert.equal(template.render(vars).trim(), 'legacy');
}
for (const file of ['templates/page.tpl', 'snipplets/templates/page.tpl']) {
    assert(read(file).indexOf("include 'snipplets/marcela/index.tpl'") < read(file).indexOf('{% elseif is_on_page %}'));
}
const app = server(4180);

(async () => {
    const browser = await chromium.launch({executablePath: 'C:/Users/rcalmeida/AppData/Local/ms-playwright/chromium-1234/chrome-win64/chrome.exe', headless: true});
    const report = [];
    try {
        const page = await browser.newPage({viewport: {width: 1440, height: 1000}, reducedMotion: 'reduce'});
        const errors = [];
        page.on('pageerror', error => errors.push(error.message));
        const requests = [];
        page.on('request', request => requests.push(request.url()));
        await page.goto(base);
        await page.waitForSelector('[data-bs-catalog-ready="1"]');
        const cards = page.locator('[data-bs-grid] > [data-be-product]');
        assert.equal(await cards.count(), 12);
        assert(!requests.some(url => url.includes('bs_category_feed')), 'curated catalog must not fetch another category');
        await page.locator('[data-bs-more]').click(); assert.equal(await cards.count(), 24);
        await page.locator('[data-bs-more]').click(); assert.equal(await cards.count(), 36);
        await page.locator('[data-bs-more]').click(); assert.equal(await cards.count(), 42);
        assert(await page.locator('[data-bs-more]').isHidden());
        report.push('catalog: curated order, deduplication, 12 initial / 12 per expansion');
        await page.locator('[data-bs-category="1"]').click();
        assert.equal(await cards.count(), 12);
        await page.locator('[data-bs-more]').click(); assert.equal(await cards.count(), 14);
        await page.locator('[data-bs-category="2"]').click();
        assert.equal(await cards.count(), 12);
        assert.equal(await page.locator('#bs-description-1').isVisible(), false);
        assert.equal(await page.locator('#bs-description-2').isVisible(), true);
        await page.locator('[data-bs-open-filters]').click();
        await page.locator('[name="bs_model"]').selectOption('prism');
        await page.locator('[data-bs-filter-form] button[type="submit"]').click();
        assert.equal(await cards.count(), 12, 'model and visual category are combined');
        assert.match(new URL(page.url()).searchParams.get('bs_filters'), /prism/);
        await page.locator('[data-bs-category="2"]').click();
        await page.locator('[data-bs-category="4"]').click();
        assert.equal(await cards.count(), 0);
        assert.match(await page.locator('[data-bs-status]').innerText(), /Nenhum produto/);
        await page.locator('[data-bs-reset]').click();
        assert.equal(await cards.count(), 12);
        await page.locator('[data-bs-sort]').selectOption('price-descending');
        assert.equal(await cards.first().getAttribute('data-be-price'), '141000');
        await page.locator('[data-bs-open-filters]').click();
        assert(await page.locator('#bs-filter-dialog').isVisible());
        await page.locator('[name="min_price"]').fill('1400');
        await page.locator('[data-bs-filter-form] button[type="submit"]').click();
        assert.equal(await cards.count(), 2);
        assert.equal(await page.locator('#bs-filter-dialog').isVisible(), false);
        await page.goBack(); assert.equal(await cards.count(), 12);
        report.push('category switching, single description, empty state, sorting, price filter, browser history');

        assert.equal(await page.locator('.mf-look').first().locator('[data-mf-look]').getAttribute('data-mf-look'), '4');
        const looksVisible = await page.locator('.mf-looks .mf-track').evaluate(track => track.clientWidth / (track.firstElementChild.getBoundingClientRect().width + 12));
        assert(looksVisible > 2 && looksVisible < 2.3);
        const founderVisible = await page.locator('.mf-founder .mf-track').evaluate(track => track.clientWidth / (track.firstElementChild.getBoundingClientRect().width + 12));
        assert(founderVisible > 4 && founderVisible < 4.3);
        const opener = page.locator('[data-mf-look]').first();
        await opener.click();
        assert(await page.locator('#mf-look-dialog').isVisible());
        assert.equal(await page.locator('[data-mf-dialog-body] [data-be-product]').count(), 2);
        assert.match(await page.locator('[data-mf-dialog-body] h3').first().innerText(), /Marcela 4/);
        assert.match(await page.locator('[data-mf-dialog-body] .be-product__info a').first().getAttribute('href'), /produtos/);
        await page.screenshot({path: path.join(temp, 'marcela-look-desktop.png')});
        await page.keyboard.press('Escape');
        assert(await page.locator('#mf-look-dialog').isHidden());
        assert(await opener.evaluate(node => node === document.activeElement));
        report.push('look ordering, two-product limit, desktop carousel continuity, dialog focus and Escape');

        await page.locator('[data-bs-reset]').click();
        await page.evaluate(async () => {
            document.querySelectorAll('img').forEach(image => image.loading = 'eager');
            await Promise.all(Array.from(document.images).map(image => image.decode().catch(() => {})));
            window.scrollTo(0, 0);
        });
        assert.equal(await page.locator('body').evaluate(body => body.scrollWidth <= window.innerWidth), true);
        await page.screenshot({path: path.join(temp, 'marcela-desktop-1440.png'), fullPage: true});
        await page.setViewportSize({width: 390, height: 844});
        await page.waitForFunction(() => document.querySelectorAll('[data-bs-grid] > [data-be-product]').length === 6);
        await page.locator('[data-bs-more]').click(); assert.equal(await cards.count(), 12);
        await page.locator('[data-bs-category="1"]').click(); assert.equal(await cards.count(), 6);
        assert(await page.locator('[data-bs-mobile-description]').isVisible());
        assert.equal(await page.locator('#bs-description-1').isVisible(), false);
        await page.locator('[data-bs-reset]').click();
        assert.equal(await page.locator('.mf-looks .mf-track').evaluate(track => Math.abs(track.clientWidth - track.firstElementChild.getBoundingClientRect().width) < 2), true);
        assert.equal(await page.locator('body').evaluate(body => body.scrollWidth <= window.innerWidth), true);
        await page.evaluate(() => window.scrollTo(0, 0));
        await page.screenshot({path: path.join(temp, 'marcela-mobile-390.png'), fullPage: true});
        await page.setViewportSize({width: 320, height: 844});
        assert.equal(await page.locator('body').evaluate(body => body.scrollWidth <= window.innerWidth), true);
        await page.locator('[data-mf-look]').first().click();
        assert.equal(await page.locator('#mf-look-dialog').evaluate(node => node.scrollWidth <= node.clientWidth), true);
        await page.screenshot({path: path.join(temp, 'marcela-look-mobile.png')});
        await page.keyboard.press('Escape');
        report.push('mobile: six products per expansion, two categories, one look/content, no horizontal overflow');

        await page.goto(base + '?empty&minimal');
        assert.equal(await cards.count(), 0);
        assert.match(await page.locator('[data-bs-status]').innerText(), /Nenhum produto/);
        assert.equal(await page.locator('[data-mf-carousel]').count(), 0);
        await page.goto(base + '?legacy&minimal');
        assert.equal(await cards.count(), 6);
        report.push('disabled/empty slots disappear; legacy campaign content survives');
        await page.route('https://player.vimeo.com/**', route => route.fulfill({contentType: 'text/html', body: '<html></html>'}));
        await page.goto(base + '?video=' + encodeURIComponent('https://vimeo.com/1183849090'));
        assert.equal(await page.locator('[data-mf-video-player] iframe').count(), 0, 'respect reduced motion');
        await page.locator('[data-mf-media-toggle]').click();
        assert.equal(await page.locator('[data-mf-video-player] iframe').count(), 1);
        await page.locator('[data-mf-media-toggle]').click();
        assert.equal(await page.locator('[data-mf-video-player] iframe').count(), 0);
        await page.goto(base + '?video=' + encodeURIComponent('javascript:alert(1)'));
        assert(await page.locator('[data-mf-media-toggle]').isHidden());
        assert.deepEqual(errors, []);
        report.push('video play/pause, reduced motion, reject unsafe media URL, original GIF URL, no console errors');
        fs.writeFileSync(path.join(temp, 'validation.json'), JSON.stringify({passed: true, report}, null, 2));
        console.log('PASS: ' + report.join('; '));
    } finally { await browser.close(); app.close(); }
})().catch(error => { console.error(error); app.close(); process.exitCode = 1; });
